class UndergroundSystem {
    private static class CheckIn{
        String station;
        int time;
        CheckIn(String station,int time){
            this.station=station;
            this.time=time;
        }
    }
    private final Map<Integer,CheckIn> active=new HashMap<>();
    private final Map<String,long[]> routes=new HashMap<>();
    public void checkIn(int id,String stationName,int t){
        active.put(id,new CheckIn(stationName,t));
    }
    public void checkOut(int id,String stationName,int t){
        CheckIn start=active.remove(id);
        long[] aggregate=routes.computeIfAbsent(start.station+"#"+stationName,key->new long[2]);
        aggregate[0]+=t-start.time;
        aggregate[1]++;
    }
    public double getAverageTime(String startStation,String endStation){
        long[] aggregate=routes.get(startStation+"#"+endStation);
        return (double)aggregate[0]/aggregate[1];
    }
}

code.kotlin:
class UndergroundSystem {
    private val active=mutableMapOf<Int,Pair<String,Int>>();
    private val routes=mutableMapOf<String,LongArray>();
    fun checkIn(id:Int,stationName:String,t:Int){
        active[id]=stationName to t
    };
    fun checkOut(id:Int,stationName:String,t:Int){
        val start=active.remove(id)!!;
        val aggregate=routes.getOrPut(start.first+"#"+stationName){
            LongArray(2)
        };
        aggregate[0]+=(t-start.second);
        aggregate[1]++
    };
    fun getAverageTime(startStation:String,endStation:String):Double{
        val aggregate=routes[startStation+"#"+endStation]!!;
        return aggregate[0].toDouble()/aggregate[1]
    }
}

code.cpp:
class UndergroundSystem {
    unordered_map<int,pair<string,int>> active;
    unordered_map<string,pair<long long,int>> routes;
    public:void checkIn(int id,string stationName,int t){
        active[id]={
            stationName,t
        };
    }
    void checkOut(int id,string stationName,int t){
        auto start=active[id];
        active.erase(id);
        auto& aggregate=routes[start.first+"#"+stationName];
        aggregate.first+=t-start.second;
        ++aggregate.second;
    }
    double getAverageTime(string startStation,string endStation){
        auto aggregate=routes[startStation+"#"+endStation];
        return (double)aggregate.first/aggregate.second;
    }
};
